local function quad(cx, cy, w, h, a, fs)
  local pts = {}
  for _, c in ipairs({{-1, -1}, {1, -1}, {1, 1}, {-1, 1}}) do
    local x, y = c[1] * w / 2, c[2] * h / 2
    local xr = x * math.cos(a) - y * math.sin(a)
    local yr = x * math.sin(a) + y * math.cos(a)
    pts[#pts + 1] = {cx + xr, cy + yr * fs}
  end
  return poly(pts)
end
